const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A point in the Norwegian Sea.
  const aoi = ee.Geometry.Point([5.0, 68.0]);
  // A date range around the specified date to increase chances of a clear image.
  const startDate = '2019-06-05';
  const endDate = '2019-06-06';

  // 2. Data Acquisition & Cloud Masking
  // Sentinel-3 OLCI is suitable for monitoring ocean color and chlorophyll.
  const collection = ee.ImageCollection('COPERNICUS/S3/OLCI')
    .filterBounds(aoi)
    .filterDate(startDate, endDate);

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Evidence: No Sentinel-3 images found for the specified date and location.');
    console.log('A: No');
    return;
  }
  console.log(`Found ${collectionSize} image(s) for the period.`);

  // Function to mask clouds using the quality flags.
  // Flags are bitmasks; we check for CLOUD and CLOUD_AMBIGUOUS.
  const maskClouds = function(image) {
    const quality = image.select('quality_flags');
    const cloudMask = 1 << 21; // CLOUD bit
    const cloudAmbiguousMask = 1 << 23; // CLOUD_AMBIGUOUS bit
    const mask = quality.bitwiseAnd(cloudMask).eq(0)
      .and(quality.bitwiseAnd(cloudAmbiguousMask).eq(0));
    // We are interested in the Chlorophyll-a concentration band.
    return image.select('Oa08_radiance').updateMask(mask);
  };

  const maskedCollection = collection.map(maskClouds);

  // 3. Processing
  // Create a mosaic of the images to get the best available pixel.
  const mosaic = maskedCollection.mosaic();

  // 4. Calculation
  // Define a reducer to get both count and mean.
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  // Calculate stats over a 10km buffer around the point. Scale is 1000m.
  const stats = mosaic.reduceRegion({
    reducer: reducer,
    geometry: aoi.buffer(10000), // 10km buffer
    scale: 1000,
    maxPixels: 1e9
  });

  const meanRadiance = stats.get('Oa08_radiance_mean').getInfo();
  const pixelCount = stats.get('Oa08_radiance_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log('Evidence: Images found, but the area was completely covered by clouds.');
    console.log('C2: No Valid Pixels');
    return;
  }

  if (meanRadiance === null || typeof meanRadiance === 'undefined') {
    console.log('Evidence: Could not calculate mean radiance.');
    console.log('C3: Calculation Failure');
    return;
  }

  // Phytoplankton blooms are indicated by higher radiance in this specific band (related to fluorescence).
  // A typical threshold for Oa08 radiance suggesting a bloom is > 1.5-2 mW m-2 sr-1 nm-1. We'll use 1.5.
  const bloomThreshold = 1.5;
  const isBloom = meanRadiance > bloomThreshold;

  console.log(`Evidence: Mean Oa08 radiance was ${meanRadiance.toFixed(2)} mW m-2 sr-1 nm-1.`);
  console.log(`Evidence: Bloom threshold is > ${bloomThreshold}.`);
  console.log(`Evidence: Number of valid (cloud-free) pixels was ${pixelCount}.`);

  if (isBloom) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
